        break
    results.extend(page)
    page_index += 1
print('total approved sent payment requests:', len(results))
# show a small sample sorted by created_at desc to inspect fields
from datetime import datetime

def parse_dt(s):
    if not s: return None
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        try:
            return datetime.strptime(s, '%Y-%m-%dT%H:%M:%S')
        except Exception:
            return None

# sort
sorted_results = sorted(results, key=lambda x: parse_dt(x.get('created_at')) or datetime.min, reverse=True)
for r in sorted_results[:8]:
    print(r['payment_request_id'], r['receiver']['name'], r['receiver']['email'], r['amount'], r.get('created_at'), r.get('approved_at'))

# Find the latest approved sent payment request where the receiver appears to be 'Cory'
approved_sent = results  # from earlier fetch

def parse_dt(s):
    if not s:
        return None
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        try:
            return datetime.strptime(s, '%Y-%m-%dT%H:%M:%S')
        except Exception:
            return None

cory_reqs = [r for r in approved_sent if r.get('receiver',{}).get('name','').lower().startswith('cory')]
# If name matching is too strict, also match substring
if not cory_reqs:
    cory_reqs = [r for r in approved_sent if 'cory' in r.get('receiver',{}).get('name','').lower()]

print('Total approved sent requests:', len(approved_sent))
print('Approved sent requests to Cory (by receiver name match):', len(cory_reqs))

# Print all matches with created_at for verification
cory_sorted = sorted(cory_reqs, key=lambda x: parse_dt(x.get('created_at')) or datetime.min, reverse=True)
for r in cory_sorted:
    print(r['payment_request_id'], r['receiver']['name'], r['receiver']['email'], r['amount'], r.get('created_at'), r.get('approved_at'))

last_cory = cory_sorted[0] if cory_sorted else None
print('LAST_CORY:', None if not last_cory else (last_cory['payment_request_id'], last_cory['receiver']['email'], last_cory['amount'], last_cory.get('created_at')))

